import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface PreloaderProps {
  onLoadingComplete: () => void;
}

const Preloader: React.FC<PreloaderProps> = ({ onLoadingComplete }) => {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setProgress((prev) => {
        if (prev >= 100) {
          clearInterval(interval);
          setTimeout(onLoadingComplete, 500);
          return 100;
        }
        return prev + Math.random() * 5;
      });
    }, 100);

    return () => clearInterval(interval);
  }, [onLoadingComplete]);

  return (
    <motion.div
      className="fixed inset-0 z-50 flex flex-col items-center justify-center bg-black"
      exit={{ opacity: 0, y: -1000, transition: { duration: 0.8, ease: "easeInOut" } }}
    >
      <div className="relative">
        {/* Neon Logo */}
        <motion.h1 
          className="text-6xl md:text-8xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyber-blue to-cyber-violet mb-8 font-mono tracking-tighter"
          initial={{ opacity: 0, scale: 0.5 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 1 }}
        >
          H.K
        </motion.h1>

        {/* Matrix Rain Effect Simulation (Simple lines for performance) */}
        <div className="absolute top-0 left-0 w-full h-full pointer-events-none opacity-20 overflow-hidden">
           {Array.from({ length: 10 }).map((_, i) => (
             <motion.div
               key={i}
               className="absolute top-0 text-cyber-blue font-mono text-xs"
               style={{ left: `${i * 10}%` }}
               initial={{ y: -100 }}
               animate={{ y: "100vh" }}
               transition={{ duration: 2 + Math.random(), repeat: Infinity, ease: "linear", delay: Math.random() }}
             >
               {Array.from({length: 20}).map(() => Math.random() > 0.5 ? '1' : '0').join('\n')}
             </motion.div>
           ))}
        </div>
      </div>

      <div className="w-64 h-1 bg-gray-800 rounded-full overflow-hidden relative">
        <motion.div 
          className="h-full bg-cyber-blue shadow-[0_0_15px_#00f3ff]"
          style={{ width: `${progress}%` }}
        />
      </div>
      <p className="mt-4 text-cyber-blue font-mono text-sm">
        INITIALIZING SYSTEM... {Math.floor(progress)}%
      </p>
    </motion.div>
  );
};

export default Preloader;

import React, { useEffect, useRef, useState } from 'react';
import { motion } from 'framer-motion';
import { HERO_TITLES } from '../constants';

const Hero: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [textIndex, setTextIndex] = useState(0);
  const [displayText, setDisplayText] = useState('');
  const [isDeleting, setIsDeleting] = useState(false);

  // Typewriter Effect
  useEffect(() => {
    const currentTitle = HERO_TITLES[textIndex];
    const timeout = setTimeout(() => {
      if (!isDeleting) {
        setDisplayText(currentTitle.substring(0, displayText.length + 1));
        if (displayText.length === currentTitle.length) {
          setTimeout(() => setIsDeleting(true), 1500);
        }
      } else {
        setDisplayText(currentTitle.substring(0, displayText.length - 1));
        if (displayText.length === 0) {
          setIsDeleting(false);
          setTextIndex((prev) => (prev + 1) % HERO_TITLES.length);
        }
      }
    }, isDeleting ? 50 : 100);

    return () => clearTimeout(timeout);
  }, [displayText, isDeleting, textIndex]);

  // Neural Network Background
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let particles: { x: number; y: number; vx: number; vy: number }[] = [];

    const resizeCanvas = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      initParticles();
    };

    const initParticles = () => {
      particles = [];
      const numberOfParticles = Math.floor((canvas.width * canvas.height) / 15000);
      for (let i = 0; i < numberOfParticles; i++) {
        particles.push({
          x: Math.random() * canvas.width,
          y: Math.random() * canvas.height,
          vx: (Math.random() - 0.5) * 0.5,
          vy: (Math.random() - 0.5) * 0.5,
        });
      }
    };

    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#00f3ff';
      ctx.strokeStyle = 'rgba(188, 19, 254, 0.15)'; // Violet connections

      particles.forEach((particle, i) => {
        particle.x += particle.vx;
        particle.y += particle.vy;

        if (particle.x < 0 || particle.x > canvas.width) particle.vx *= -1;
        if (particle.y < 0 || particle.y > canvas.height) particle.vy *= -1;

        ctx.beginPath();
        ctx.arc(particle.x, particle.y, 2, 0, Math.PI * 2);
        ctx.fill();

        for (let j = i + 1; j < particles.length; j++) {
          const dx = particles[j].x - particle.x;
          const dy = particles[j].y - particle.y;
          const distance = Math.sqrt(dx * dx + dy * dy);

          if (distance < 150) {
            ctx.beginPath();
            ctx.moveTo(particle.x, particle.y);
            ctx.lineTo(particles[j].x, particles[j].y);
            ctx.stroke();
          }
        }
      });

      animationFrameId = requestAnimationFrame(draw);
    };

    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();
    draw();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <section id="home" className="relative h-screen w-full flex items-center justify-center overflow-hidden bg-cyber-black">
      <canvas ref={canvasRef} className="absolute inset-0 z-0 opacity-50" />

      <div className="z-10 container mx-auto px-4 grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
        {/* Left: Text */}
        <motion.div 
          className="order-2 md:order-1 text-center md:text-left"
          initial={{ opacity: 0, x: -50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 1 }}
        >
          <p className="text-cyber-blue font-mono mb-4 text-lg">Hello, je suis</p>
          <h1 className="text-5xl md:text-7xl font-bold mb-4 bg-clip-text text-transparent bg-gradient-to-r from-white to-gray-400">
            Hassane <span className="block text-cyber-violet">Kone</span>
          </h1>
          <div className="h-16">
            <span className="text-2xl md:text-4xl font-mono text-gray-300">
              {displayText}
              <span className="animate-pulse">|</span>
            </span>
          </div>
          <p className="mt-6 text-gray-400 max-w-lg mx-auto md:mx-0">
            L'architecte de vos ambitions numériques : Du code sur-mesure à l'intelligence artificielle.
          </p>

          <div className="mt-8 flex gap-4 justify-center md:justify-start">
             <a href="#projects" className="px-8 py-3 bg-cyber-blue/10 border border-cyber-blue text-cyber-blue rounded-none hover:bg-cyber-blue hover:text-black transition-all duration-300 font-bold uppercase tracking-widest text-sm">
                Voir Projets
             </a>
             <a href="#contact" className="px-8 py-3 bg-transparent border border-white/20 text-white hover:border-cyber-violet hover:text-cyber-violet transition-all duration-300 font-bold uppercase tracking-widest text-sm">
                Me Contacter
             </a>
          </div>
        </motion.div>

        {/* Right: Photo/Visual */}
        <motion.div 
          className="order-1 md:order-2 flex justify-center"
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 1, delay: 0.2 }}
        >
          <div className="relative w-72 h-72 md:w-96 md:h-96">
            <div className="absolute inset-0 bg-cyber-violet/20 rounded-full blur-3xl animate-pulse"></div>
            <div className="relative w-full h-full rounded-full border-2 border-cyber-blue/30 overflow-hidden backdrop-blur-sm bg-white/5 flex items-center justify-center">
               {/* Placeholder for real photo - using a cool tech avatar concept if no photo provided, but user said "Ta photo" */}
               <img 
                 src="https://picsum.photos/400/400" 
                 alt="Hassane Kone" 
                 className="w-full h-full object-cover opacity-90 hover:scale-110 transition-transform duration-700"
               />
            </div>
            {/* Orbiting Elements decoration */}
            <div className="absolute top-0 left-0 w-full h-full animate-spin-slow border border-dashed border-cyber-blue/20 rounded-full pointer-events-none"></div>
            <div className="absolute -inset-4 animate-reverse-spin border border-dotted border-cyber-violet/20 rounded-full pointer-events-none"></div>
          </div>
        </motion.div>
      </div>

      {/* Scroll indicator */}
      <motion.div 
        className="absolute bottom-10 left-1/2 -translate-x-1/2"
        animate={{ y: [0, 10, 0] }}
        transition={{ duration: 2, repeat: Infinity }}
      >
        <div className="w-6 h-10 border-2 border-white/20 rounded-full flex justify-center pt-2">
          <div className="w-1 h-2 bg-cyber-blue rounded-full"></div>
        </div>
      </motion.div>
    </section>
  );
};

export default Hero;

