import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Bot, X, Send, Sparkles } from 'lucide-react';

interface Message {
  id: number;
  text: string;
  sender: 'bot' | 'user';
}

const Chatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: 1, text: "Bonjour ! Je suis l'assistant IA de Hassane. Posez-moi des questions sur ses compétences, tarifs ou disponibilités.", sender: 'bot' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(scrollToBottom, [messages, isTyping]);

  const handleSend = () => {
    if (!input.trim()) return;

    const userMsg: Message = { id: Date.now(), text: input, sender: 'user' };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    // Simulated AI Logic
    setTimeout(() => {
      let botResponse = "Je n'ai pas compris. Pouvez-vous reformuler ?";
      const lowerInput = userMsg.text.toLowerCase();

      if (lowerInput.includes('tarif') || lowerInput.includes('prix') || lowerInput.includes('coût')) {
        botResponse = "Les tarifs dépendent de la complexité du projet. Pour un site vitrine, comptez à partir de 200.000 FCFA. Pour une app mobile complexe, contactez Hassane directement.";
      } else if (lowerInput.includes('dispo') || lowerInput.includes('quand')) {
        botResponse = "Hassane est actuellement disponible pour de nouveaux projets freelances. Le délai de démarrage est d'environ 1 semaine.";
      } else if (lowerInput.includes('tech') || lowerInput.includes('stack') || lowerInput.includes('langage')) {
        botResponse = "Sa stack principale : React.js, Node.js, Flutter pour le mobile, et Python/n8n pour l'automatisation IA.";
      } else if (lowerInput.includes('contact') || lowerInput.includes('mail') || lowerInput.includes('numéro')) {
        botResponse = "Vous pouvez le joindre au +225 0594671766 ou via le formulaire de contact du site.";
      } else if (lowerInput.includes('bonjour') || lowerInput.includes('salut')) {
        botResponse = "Salut ! Comment puis-je vous aider aujourd'hui ?";
      }

      const botMsg: Message = { id: Date.now() + 1, text: botResponse, sender: 'bot' };
      setMessages(prev => [...prev, botMsg]);
      setIsTyping(false);
    }, 1500);
  };

  return (
    <>
      {/* Trigger Button (Left side as requested) */}
      <motion.button
        className="fixed bottom-6 left-6 z-40 bg-cyber-violet text-white p-4 rounded-full shadow-lg shadow-cyber-violet/30 hover:shadow-cyber-violet/50 transition-shadow"
        onClick={() => setIsOpen(!isOpen)}
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
      >
        {isOpen ? <X size={24} /> : <Bot size={24} />}
      </motion.button>

      {/* Chat Window */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 50, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 50, scale: 0.9 }}
            className="fixed bottom-24 left-6 z-40 w-80 md:w-96 bg-[#121212] border border-white/10 rounded-2xl shadow-2xl overflow-hidden flex flex-col"
          >
            {/* Header */}
            <div className="bg-gradient-to-r from-cyber-violet to-purple-800 p-4 flex items-center gap-3">
              <div className="p-2 bg-white/20 rounded-full">
                <Sparkles size={16} className="text-white" />
              </div>
              <div>
                <h3 className="font-bold text-white text-sm">Hassane AI Assistant</h3>
                <span className="flex items-center gap-1 text-[10px] text-gray-200">
                  <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></span> En ligne
                </span>
              </div>
            </div>

            {/* Messages */}
            <div className="flex-1 h-80 overflow-y-auto p-4 space-y-4 bg-black/50">
              {messages.map((msg) => (
                <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] p-3 rounded-2xl text-sm ${
                    msg.sender === 'user' 
                      ? 'bg-cyber-violet text-white rounded-tr-none' 
                      : 'bg-gray-800 text-gray-200 rounded-tl-none'
                  }`}>
                    {msg.text}
                  </div>
                </div>
              ))}
              {isTyping && (
                 <div className="flex justify-start">
                   <div className="bg-gray-800 p-3 rounded-2xl rounded-tl-none flex gap-1">
                     <span className="w-2 h-2 bg-gray-500 rounded-full animate-bounce"></span>
                     <span className="w-2 h-2 bg-gray-500 rounded-full animate-bounce delay-75"></span>
                     <span className="w-2 h-2 bg-gray-500 rounded-full animate-bounce delay-150"></span>
                   </div>
                 </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Input */}
            <div className="p-3 border-t border-white/10 bg-[#121212]">
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                  placeholder="Posez une question..."
                  className="flex-1 bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-cyber-violet"
                />
                <button 
                  onClick={handleSend}
                  className="p-2 bg-cyber-violet rounded-lg text-white hover:bg-purple-600 transition-colors"
                >
                  <Send size={18} />
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
};

export default Chatbot;

