const ServiceCard: React.FC<{ service: Service; index: number; onOpen: (s: Service) => void }> = ({ service, index, onOpen }) => {
  const divRef = useRef<HTMLDivElement>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const opacity = useMotionValue(0);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!divRef.current) return;
    const rect = divRef.current.getBoundingClientRect();
    setPosition({ x: e.clientX - rect.left, y: e.clientY - rect.top });
  };

  return (
    <motion.div
      ref={divRef}
      onMouseMove={handleMouseMove}
      onMouseEnter={() => { setIsFocused(true); opacity.set(1); }}
      onMouseLeave={() => { setIsFocused(false); opacity.set(0); }}
      initial={{ opacity: 0, y: 50 }}
      whileInView={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: index * 0.1 }}
      className="relative h-full rounded-3xl border border-white/10 bg-gray-900/40 px-8 py-10 overflow-hidden group backdrop-blur-sm cursor-pointer"
      onClick={() => onOpen(service)}
    >
      <div
        className="pointer-events-none absolute -inset-px transition duration-300"
        style={{
          opacity: isFocused ? 1 : 0,
          background: `radial-gradient(600px circle at ${position.x}px ${position.y}px, rgba(188,19,254,0.15), transparent 40%)`,
        }}
      />

      <div
        className="pointer-events-none absolute -inset-px rounded-3xl opacity-0 transition duration-300 group-hover:opacity-100"
        style={{
          background: `radial-gradient(600px circle at ${position.x}px ${position.y}px, rgba(0,243,255,0.4), transparent 40%)`,
          maskImage: `linear-gradient(black, black) content-box, linear-gradient(black, black)`,
          WebkitMaskImage: `linear-gradient(black, black) content-box, linear-gradient(black, black)`,
          maskComposite: 'exclude',
          WebkitMaskComposite: 'xor',
        }}
      />

      <div className="relative z-10 flex flex-col h-full">
        <div className="mb-8 flex items-center justify-between">
          <motion.div 
            className="relative flex h-16 w-16 items-center justify-center rounded-2xl bg-white/5 shadow-inner border border-white/10 group-hover:border-cyber-blue/50 transition-colors duration-500"
            animate={{ y: [0, -5, 0] }}
            transition={{ duration: 4, repeat: Infinity, ease: "easeInOut", delay: index * 0.5 }}
