        </div>

        <h3 className="mb-4 text-2xl font-bold text-white group-hover:text-transparent group-hover:bg-clip-text group-hover:bg-gradient-to-r group-hover:from-white group-hover:to-cyber-blue transition-all duration-300">
          {service.title}
        </h3>

        <p className="mb-8 text-base leading-relaxed text-gray-400 group-hover:text-gray-300 transition-colors flex-grow">
          {service.description}
        </p>

        <div className="mt-auto">
          <button className="flex items-center gap-2 text-sm font-bold text-cyber-violet group-hover:text-cyber-blue transition-colors uppercase tracking-widest">
            En savoir plus 
            <ArrowRight size={16} className="transform group-hover:translate-x-1 transition-transform" />
          </button>
        </div>
      </div>
    </motion.div>
  );
};

