const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeSection, setActiveSection] = useState('home');

  // Gestion du scroll pour le style et la détection de section
  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);

      // Détecter quelle section est visible
      const sections = LINKS.map(link => document.getElementById(link.id));
      const scrollPosition = window.scrollY + 100;

      sections.forEach((section) => {
        if (section) {
          const top = section.offsetTop;
          const height = section.offsetHeight;
          if (scrollPosition >= top && scrollPosition < top + height) {
            setActiveSection(section.id);
          }
        }
      });
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 80; // Hauteur de la navbar
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = element.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
      setIsOpen(false);
    }
  };

  // Variantes d'animation pour le menu mobile
  const menuVariants = {
    closed: {
      opacity: 0,
      scale: 0.95,
      transition: { staggerChildren: 0.05, staggerDirection: -1 }
    },
    open: {
      opacity: 1,
      scale: 1,
      transition: { 
        staggerChildren: 0.1, 
        delayChildren: 0.2,
        type: "spring",
        stiffness: 100,
        damping: 20
      }
    }
  };

  const itemVariants = {
    closed: { x: -20, opacity: 0 },
    open: { x: 0, opacity: 1 }
  };

  return (
    <nav 
      className={`fixed top-0 w-full z-50 transition-all duration-500 ${
        scrolled 
          ? 'bg-black/40 backdrop-blur-2xl border-b border-white/5 py-4' 
          : 'bg-transparent py-7'
      }`}
    >
      <div className="container mx-auto px-6 flex justify-between items-center">
        {/* Logo interactif */}
        <motion.button 
          onClick={() => scrollToSection('home')}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className="relative z-50 text-3xl font-black font-mono tracking-tighter"
        >
          <span className="text-transparent bg-clip-text bg-gradient-to-r from-cyber-blue to-cyber-violet">H.K</span>
          <motion.div 
            initial={{ width: 0 }}
            whileHover={{ width: '100%' }}
            className="absolute -bottom-1 left-0 h-0.5 bg-gradient-to-r from-cyber-blue to-cyber-violet"
          />
        </motion.button>

        {/* Desktop Menu - Style International */}
        <div className="hidden xl:flex items-center bg-white/5 border border-white/10 rounded-full px-2 py-1.5 backdrop-blur-md">
          {LINKS.map((link) => {
            const isActive = activeSection === link.id;
            return (
              <button 
                key={link.id} 
                onClick={() => scrollToSection(link.id)}
                className={`px-4 py-2 text-xs font-bold uppercase tracking-widest transition-all duration-300 relative rounded-full ${
                  isActive ? 'text-white' : 'text-gray-400 hover:text-white'
                }`}
              >
                {isActive && (
                  <motion.div 
                    layoutId="nav-active-pill"
                    className="absolute inset-0 bg-white/10 rounded-full z-[-1]"
                    transition={{ type: "spring", bounce: 0.25, duration: 0.5 }}
                  />
                )}
                {link.name}
              </button>
            );
          })}
        </div>

        {/* Bouton Recruter - Look Pro */}
        <div className="hidden xl:block">
          <motion.button 
            onClick={() => scrollToSection('contact')}
            whileHover={{ scale: 1.05, boxShadow: "0 0 20px rgba(188, 19, 254, 0.4)" }}
            whileTap={{ scale: 0.95 }}
            className="px-6 py-2.5 bg-gradient-to-r from-cyber-blue/10 to-cyber-violet/10 border border-cyber-violet/30 text-white rounded-full text-xs font-black uppercase tracking-widest hover:border-cyber-violet transition-all flex items-center gap-2"
          >
            Démarrer un projet <ArrowRight size={14} className="text-cyber-blue" />
          </motion.button>
        </div>

        {/* Mobile Toggle avec animation Spring */}
        <motion.button 
          className="xl:hidden relative z-50 w-12 h-12 flex items-center justify-center rounded-full bg-white/5 border border-white/10"
          onClick={() => setIsOpen(!isOpen)}
          whileTap={{ scale: 0.8 }}
        >
          {isOpen ? <X size={24} className="text-cyber-violet" /> : <Menu size={24} className="text-cyber-blue" />}
        </motion.button>
      </div>

      {/* Menu Mobile - Overlay "International Standard" */}
      <AnimatePresence>
        {isOpen && (
          <>
            {/* Backdrop Blur Overlay */}
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsOpen(false)}
              className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 xl:hidden"
            />

            <motion.div 
              variants={menuVariants}
              initial="closed"
              animate="open"
              exit="closed"
              className="fixed top-0 right-0 w-[80%] max-w-sm h-screen bg-[#0a0a0a] border-l border-white/10 z-50 xl:hidden flex flex-col pt-32 px-8 shadow-2xl"
            >
              <div className="absolute top-10 left-8">
