import React, { useEffect, useRef, useState } from 'react';
import { motion, useMotionValue, useTransform, useSpring } from 'framer-motion';
import { HERO_TITLES } from '../constants';

const Hero: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [textIndex, setTextIndex] = useState(0);
  const [displayText, setDisplayText] = useState('');
  const [isDeleting, setIsDeleting] = useState(false);

  // Mouse tracking for parallax
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const mouseXSpring = useSpring(x, { stiffness: 150, damping: 20 });
  const mouseYSpring = useSpring(y, { stiffness: 150, damping: 20 });

  const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], ["10deg", "-10deg"]);
  const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], ["-10deg", "10deg"]);

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    x.set(mouseX / width - 0.5);
    y.set(mouseY / height - 0.5);
  };

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  // Typewriter Effect
  useEffect(() => {
    const currentTitle = HERO_TITLES[textIndex];
    const timeout = setTimeout(() => {
      if (!isDeleting) {
        setDisplayText(currentTitle.substring(0, displayText.length + 1));
        if (displayText.length === currentTitle.length) {
          setTimeout(() => setIsDeleting(true), 1500);
        }
      } else {
        setDisplayText(currentTitle.substring(0, displayText.length - 1));
        if (displayText.length === 0) {
          setIsDeleting(false);
          setTextIndex((prev) => (prev + 1) % HERO_TITLES.length);
        }
      }
    }, isDeleting ? 50 : 100);

    return () => clearTimeout(timeout);
  }, [displayText, isDeleting, textIndex]);

  // Neural Network Background (Existing logic kept for visual consistency)
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    let animationFrameId: number;
    let particles: { x: number; y: number; vx: number; vy: number }[] = [];
    const resizeCanvas = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      initParticles();
    };
    const initParticles = () => {
      particles = [];
      const numberOfParticles = Math.floor((canvas.width * canvas.height) / 15000);
      for (let i = 0; i < numberOfParticles; i++) {
        particles.push({
          x: Math.random() * canvas.width,
          y: Math.random() * canvas.height,
          vx: (Math.random() - 0.5) * 0.5,
          vy: (Math.random() - 0.5) * 0.5,
        });
      }
    };
    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#00f3ff';
      ctx.strokeStyle = 'rgba(188, 19, 254, 0.15)'; 
      particles.forEach((particle, i) => {
        particle.x += particle.vx;
        particle.y += particle.vy;
        if (particle.x < 0 || particle.x > canvas.width) particle.vx *= -1;
        if (particle.y < 0 || particle.y > canvas.height) particle.vy *= -1;
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, 2, 0, Math.PI * 2);
        ctx.fill();
        for (let j = i + 1; j < particles.length; j++) {
          const dx = particles[j].x - particle.x;
          const dy = particles[j].y - particle.y;
          const distance = Math.sqrt(dx * dx + dy * dy);
          if (distance < 150) {
            ctx.beginPath();
            ctx.moveTo(particle.x, particle.y);
            ctx.lineTo(particles[j].x, particles[j].y);
            ctx.stroke();
          }
        }
      });
      animationFrameId = requestAnimationFrame(draw);
    };
    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();
    draw();
    return () => {
      window.removeEventListener('resize', resizeCanvas);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <section 
      id="home" 
      onMouseMove={handleMouseMove}
      className="relative min-h-screen w-full flex items-center justify-center overflow-hidden bg-cyber-black py-20"
    >
      <canvas ref={canvasRef} className="absolute inset-0 z-0 opacity-50 pointer-events-none" />

      <div className="z-10 container mx-auto px-4 grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
        {/* Left: Text */}
        <div className="order-2 md:order-1 text-center md:text-left">
          <motion.p 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="text-cyber-blue font-mono mb-4 text-lg"
          >
            Hello, je suis
          </motion.p>

          <motion.h1 
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, delay: 0.2 }}
            className="text-4xl md:text-6xl lg:text-7xl font-bold mb-4 bg-clip-text text-transparent bg-gradient-to-r from-white to-gray-400 leading-tight"
          >
            Hassane Olivier <br className="hidden md:block" /> Franck <span className="block text-cyber-violet">Kone</span>
          </motion.h1>

          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.5 }}
            className="h-16"
          >
            <span className="text-2xl md:text-4xl font-mono text-gray-300">
              {displayText}
              <span className="animate-pulse">|</span>
            </span>
          </motion.div>

          <motion.p 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.8 }}
            className="mt-6 text-gray-400 max-w-lg mx-auto md:mx-0"
          >
            L'architecte de vos ambitions numériques : Du code sur-mesure à l'intelligence artificielle pour propulser votre business.
          </motion.p>

          <motion.div 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 1 }}
            className="mt-8 flex gap-4 justify-center md:justify-start"
          >
             <button 
               onClick={() => scrollToSection('projects')}
               className="px-8 py-3 bg-cyber-blue/10 border border-cyber-blue text-cyber-blue rounded-full hover:bg-cyber-blue hover:text-black transition-all duration-300 font-bold uppercase tracking-widest text-sm relative overflow-hidden group"
             >
                <span className="relative z-10">Voir Projets</span>
                <div className="absolute inset-0 bg-cyber-blue scale-x-0 group-hover:scale-x-100 transition-transform origin-left duration-500 z-0"></div>
             </button>
             <button 
               onClick={() => scrollToSection('contact')}
               className="px-8 py-3 bg-transparent border border-white/20 text-white rounded-full hover:border-cyber-violet hover:text-cyber-violet transition-all duration-300 font-bold uppercase tracking-widest text-sm"
             >
                Me Contacter
             </button>
          </motion.div>
        </div>

        {/* Right: Photo/Visual with 3D Parallax */}
        <motion.div 
          style={{ rotateX, rotateY, transformStyle: "preserve-3d" }}
          className="order-1 md:order-2 flex justify-center"
        >
          <div className="relative w-72 h-72 md:w-96 md:h-96" style={{ transform: "translateZ(50px)" }}>
            <div className="absolute inset-0 bg-cyber-violet/20 rounded-full blur-3xl animate-pulse"></div>
            <motion.div 
              className="relative w-full h-full rounded-full border-2 border-cyber-blue/30 overflow-hidden backdrop-blur-sm bg-white/5 flex items-center justify-center"
              whileHover={{ scale: 1.05 }}
            >
               <img 
                 src="https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&q=80&w=800" 
                 alt="Hassane Olivier Franck Kone" 
                 className="w-full h-full object-cover opacity-90 hover:opacity-100 transition-opacity"
               />
            </motion.div>
            {/* Spinning Rings */}
            <div className="absolute top-0 left-0 w-full h-full animate-spin-slow border border-dashed border-cyber-blue/20 rounded-full pointer-events-none"></div>
            <div className="absolute -inset-4 animate-reverse-spin border border-dotted border-cyber-violet/20 rounded-full pointer-events-none"></div>
          </div>
        </motion.div>
      </div>
    </section>
  );
};

