import React, { useState, useRef } from 'react';
import { motion, AnimatePresence, useMotionValue, useSpring, useTransform } from 'framer-motion';
import { PROJECTS } from '../constants';
import { Project } from '../types';
import { X, ExternalLink, Send, ArrowUpRight } from 'lucide-react';

const ProjectCard = ({ project, index, onClick }: { project: Project, index: number, onClick: () => void }) => {
  const cardRef = useRef<HTMLDivElement>(null);

  // 3D Tilt Logic
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const mouseXSpring = useSpring(x);
  const mouseYSpring = useSpring(y);

  const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], ["10deg", "-10deg"]);
  const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], ["-10deg", "10deg"]);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    x.set(mouseX / width - 0.5);
    y.set(mouseY / height - 0.5);
  };

  const handleMouseLeave = () => {
    x.set(0);
    y.set(0);
  };

  return (
    <motion.div
      ref={cardRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{ rotateX, rotateY, transformStyle: "preserve-3d" }}
      initial={{ opacity: 0, y: 30 }}
      whileInView={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.1, duration: 0.8 }}
      onClick={onClick}
      className="relative group cursor-none h-[450px] w-full rounded-[32px] overflow-hidden bg-white/[0.03] border border-white/10"
    >
      {/* Background Image with Zoom */}
      <motion.img 
        src={project.image} 
        alt={project.title} 
        className="absolute inset-0 w-full h-full object-cover opacity-60 group-hover:opacity-80 group-hover:scale-110 transition-all duration-700 ease-out"
      />

      {/* Custom Cursor Overlay */}
      <div className="absolute inset-0 z-30 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center pointer-events-none">
        <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mix-blend-difference scale-0 group-hover:scale-100 transition-transform duration-500">
          <ArrowUpRight className="text-black" />
        </div>
      </div>

      <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-transparent z-10" />

      <div className="absolute bottom-0 left-0 p-8 z-20 w-full" style={{ transform: "translateZ(30px)" }}>
        <div className="flex flex-wrap gap-2 mb-4">
          {project.tech.slice(0, 2).map(t => (
            <span key={t} className="px-3 py-1 bg-white/10 backdrop-blur-md rounded-full text-[10px] font-mono text-white/70 uppercase tracking-widest border border-white/10">
              {t}
            </span>
          ))}
        </div>
        <h3 className="text-3xl font-black text-white mb-2 leading-none uppercase italic">{project.title}</h3>
        <p className="text-sm text-gray-400 font-medium line-clamp-2 max-w-[90%]">
          {project.description}
        </p>
      </div>
    </motion.div>
  );
};

const Projects: React.FC = () => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);

  const handleStartSimilarProject = () => {
    const projectName = selectedProject?.title;
    setSelectedProject(null);
    setTimeout(() => {
      const contactSection = document.getElementById('contact');
      if (contactSection) {
        contactSection.scrollIntoView({ behavior: 'smooth' });
        const textarea = document.querySelector('textarea');
        if (textarea) {
          textarea.value = `Bonjour Hassane, j'ai vu votre projet "${projectName}" et j'aimerais réaliser quelque chose de similaire...`;
          textarea.focus();
        }
      }
    }, 100);
  };

  return (
    <section id="projects" className="py-32 bg-cyber-black overflow-hidden">
      <div className="container mx-auto px-4">
        <motion.div 
          initial={{ opacity: 0, x: -50 }}
          whileInView={{ opacity: 1, x: 0 }}
          className="mb-20 text-center md:text-left flex flex-col md:flex-row md:items-end justify-between gap-8"
        >
          <div>
            <h2 className="text-5xl md:text-8xl font-black uppercase tracking-tighter leading-none">
              Lab <br/> <span className="text-cyber-violet">Créatif</span>
            </h2>
          </div>
          <p className="text-gray-500 max-w-sm font-mono text-xs uppercase tracking-[0.3em] mb-4">
            Une sélection rigoureuse de réalisations complexes & innovantes.
          </p>
        </motion.div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
          {PROJECTS.map((project, index) => (
            <ProjectCard 
              key={project.id} 
              project={project} 
              index={index} 
              onClick={() => setSelectedProject(project)} 
            />
          ))}
        </div>
      </div>

      <AnimatePresence>
        {selectedProject && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl"
            onClick={() => setSelectedProject(null)}
          >
            <motion.div
              initial={{ scale: 0.9, y: 50, opacity: 0 }}
              animate={{ scale: 1, y: 0, opacity: 1 }}
              exit={{ scale: 0.9, y: 50, opacity: 0 }}
              className="bg-[#0a0a0a] border border-white/10 rounded-[40px] max-w-4xl w-full overflow-hidden shadow-2xl"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="grid grid-cols-1 md:grid-cols-2">
                <div className="h-80 md:h-full relative overflow-hidden">
                  <img src={selectedProject.image} alt={selectedProject.title} className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-r from-black/50 to-transparent"></div>
                </div>

                <div className="p-10 md:p-16 flex flex-col justify-center">
                  <button onClick={() => setSelectedProject(null)} className="absolute top-8 right-8 text-gray-500 hover:text-white transition-colors">
                    <X size={32} strokeWidth={1} />
                  </button>

                  <p className="text-cyber-blue font-mono text-[10px] uppercase tracking-[0.5em] mb-4">{selectedProject.category}</p>
                  <h3 className="text-4xl md:text-6xl font-black text-white mb-6 uppercase tracking-tighter">{selectedProject.title}</h3>
                  <p className="text-gray-400 text-lg mb-8 leading-relaxed italic border-l-2 border-cyber-violet pl-6">
                    "{selectedProject.description}"
                  </p>

                  <div className="flex flex-wrap gap-2 mb-10">
                    {selectedProject.tech.map(t => (
                      <span key={t} className="px-4 py-1.5 bg-white/5 border border-white/10 rounded-full text-xs font-bold text-gray-300">
                        {t}
                      </span>
                    ))}
                  </div>

                  <div className="flex gap-4">
                    <button 
                      onClick={handleStartSimilarProject}
                      className="flex-1 py-5 bg-white text-black font-black uppercase tracking-widest text-xs rounded-full hover:bg-cyber-blue transition-all"
                    >
                      Initier ce projet
                    </button>
                    <button className="p-5 border border-white/10 rounded-full hover:border-white transition-all">
                      <ExternalLink size={20} />
                    </button>
                  </div>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </section>
  );
};

export default Projects;

